if [[ -z "${__SRC__Volumes_normdev_normdev_static_maiass_whole_bashmaiass_lib_core_ci_templates_sh:-}" ]]; then __SRC__Volumes_normdev_normdev_static_maiass_whole_bashmaiass_lib_core_ci_templates_sh=1

# shellcheck shell=bash
# ---------------------------------------------------------------
# ci-templates.sh — CI-template "spawner" (parity with node CLI lib/ci-templates.js)
#
# Provides three run-and-exit commands:
#   --create-gh-action  → write .github/workflows/maiass-version-bump.yml
#   --show-gl-excerpt   → print a GitLab CI excerpt to stdout
#   --show-bb-excerpt   → print a Bitbucket Pipelines excerpt to stdout
#
# RUNTIME TEMPLATE RESOLUTION
# ---------------------------
# The node CLI reads template files from <package>/templates/ci at runtime. The
# bash CLI ships as a SINGLE bundled, base64-packed file (see scripts/bundle-bash.sh
# + Makefile: `--obfuscate=pack`). There is no companion templates/ directory at a
# brew/install-script install — only the one script and its symlinks. So the
# template bodies are embedded here verbatim inside quoted heredocs and rendered
# in-memory. The canonical copies live in templates/ci/*.yml (kept byte-identical
# to the node CLI's) and are the source of truth; these heredocs must be kept in
# sync with them. A quoted heredoc delimiter ('MAIASS_CI_TEMPLATE_EOF') means the
# shell performs NO expansion inside the body, so $GH_PAT, ${{ secrets.* }},
# $GITHUB_STEP_SUMMARY, $CI_SERVER_HOST etc. survive untouched — exactly the YAML
# the user needs. Only the __MAIASS_DEVELOPBRANCH__ placeholder is substituted, by
# explicit bash parameter expansion (mirrors node's replaceAll).
#
# MAIASS_CI_FAIL_SILENTLY is NOT a render-time placeholder. It is a plain,
# editable env var hardcoded (default "false") inside the generated workflow
# files and read at runtime by the CI job — the user edits it in the YAML itself,
# not in .env.maiass. (Final shape, matching the node CLI.)
# ---------------------------------------------------------------

# Render a template body (passed on stdin) by substituting the develop-branch
# placeholder for the user's configured value at the moment the command runs.
# Shared contract with the node CLI (lib/ci-templates.js renderTemplate):
#   __MAIASS_DEVELOPBRANCH__  → $MAIASS_DEVELOPBRANCH, trimmed, default 'develop'
# After substitution there must be NO __MAIASS...__ placeholder left.
maiass_ci_render_template() {
  local body
  # Read entire stdin (preserve newlines; trailing newline normalised by printf below)
  body="$(cat)"

  # Develop branch: trim surrounding whitespace, default to 'develop' when empty.
  # Guards against a stray newline / mis-quoted .env.maiass entry silently
  # breaking the YAML trigger filter (parity with node's .trim()).
  local develop_branch="${MAIASS_DEVELOPBRANCH:-develop}"
  # Trim leading/trailing whitespace (Bash 3.2-safe).
  develop_branch="${develop_branch#"${develop_branch%%[![:space:]]*}"}"
  develop_branch="${develop_branch%"${develop_branch##*[![:space:]]}"}"
  [[ -z "$develop_branch" ]] && develop_branch="develop"

  # Substitute ALL occurrences of the placeholder (parity with node replaceAll).
  body="${body//__MAIASS_DEVELOPBRANCH__/$develop_branch}"

  printf '%s\n' "$body"
}

# Emit the raw GitHub Actions version-bump workflow template (placeholders intact).
maiass_ci_template_github() {
  cat <<'MAIASS_CI_TEMPLATE_EOF'
# MAIASS — GitHub Actions: Auto Version Bump on PR Merge
#
# What this does:
#   When a pull request is merged into your develop branch, this workflow
#   automatically runs `maiass -a patch` to bump the patch version, commit
#   the change, and push it back.
#
# Setup:
#   1. Set MAIASS_DEVELOPBRANCH in your .env.maiass if your develop branch
#      isn't called 'develop', then run `maiass --create-gh-action` so the
#      branch name is baked into the installed workflow (defaults to 'develop'
#      when unset).
#   2. Create a fine-grained Personal Access Token (PAT) with:
#        - Contents: Read & Write
#        - Metadata: Read-only
#        - Workflows: Read & Write
#   3. Add the PAT as a repository secret named GH_PAT
#
# Notes:
#   - If the GH_PAT secret is missing, this workflow runs a preflight that, by
#     default, fails with a clear message (the merge itself is unaffected — this
#     runs after merge). To instead skip with a warning and keep the run green,
#     set MAIASS_CI_FAIL_SILENTLY to "true" in the preflight step's env: block
#     below.
#   - AI is disabled (MAIASS_AI_MODE: off) so no credits are used.
#   - The branch name below is substituted at install time from
#     MAIASS_DEVELOPBRANCH. GitHub Actions requires `on.pull_request.branches`
#     to be a YAML literal, so it cannot be read from env at runtime. Edit
#     this file manually only if you rename your develop branch after install.
#   - maiass pulls the latest of that branch before bumping to prevent stale
#     version conflicts.

name: Version Bump on PR Merge

on:
  pull_request:
    types: [closed]
    branches:
      - __MAIASS_DEVELOPBRANCH__

jobs:
  bump-version:
    # Only run when the PR was actually merged (not just closed)
    if: github.event.pull_request.merged == true
    runs-on: ubuntu-latest

    permissions:
      contents: write  # Required to push the version bump commit

    steps:
      # Preflight: this workflow runs AFTER the PR is merged, so a missing
      # GH_PAT can't block the merge — but it would fail the checkout/push with
      # a confusing auth error on every merge. Detect the empty secret up front
      # and emit a clear, actionable message. Behaviour is controlled by the
      # MAIASS_CI_FAIL_SILENTLY env var below:
      #   false (default) — fail the run so the missing secret is noticed.
      #   true            — skip with a warning; the run stays green.
      - name: Check GH_PAT secret
        id: preflight
        env:
          GH_PAT: ${{ secrets.GH_PAT }}
          # Edit this to "true" to skip with a warning instead of failing when
          # GH_PAT is missing.
          MAIASS_CI_FAIL_SILENTLY: "false"
        run: |
          if [ -n "$GH_PAT" ]; then
            exit 0
          fi
          MSG="GH_PAT secret is not set, so the version bump cannot be pushed back to the repo. Add a fine-grained PAT as a repo secret named GH_PAT (Settings → Secrets → Actions) with Contents: Read & Write, Metadata: Read-only, Workflows: Read & Write."
          {
            echo "### ⚠️ MAIASS version bump — GH_PAT missing"
            echo ""
            echo "$MSG"
          } >> "$GITHUB_STEP_SUMMARY"
          if [ "$MAIASS_CI_FAIL_SILENTLY" = "true" ]; then
            echo "::warning title=MAIASS version bump skipped::$MSG"
            echo "skip=true" >> "$GITHUB_OUTPUT"
          else
            echo "::error title=MAIASS version bump failed::$MSG"
            exit 1
          fi

      - uses: actions/checkout@v4
        if: steps.preflight.outputs.skip != 'true'
        with:
          fetch-depth: 0          # Full history needed for changelog generation
          token: ${{ secrets.GH_PAT }}  # PAT allows the bot to push back to the repo

      - uses: actions/setup-node@v4
        if: steps.preflight.outputs.skip != 'true'
        with:
          node-version: '24'
          # No cache: this workflow only does `npm install -g maiass`, which
          # needs no project-level npm cache. Setting cache: 'npm' makes
          # setup-node fail on projects without a Node lock file (e.g.
          # WordPress/PHP plugins): "Dependencies lock file is not found".

      - name: Install maiass
        if: steps.preflight.outputs.skip != 'true'
        run: npm install -g maiass --no-fund --no-audit

      - name: Configure git
        if: steps.preflight.outputs.skip != 'true'
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"

      # Explicitly check out the develop branch head (the pull_request closed
      # event checks out a merge ref, not the branch itself)
      - name: Checkout __MAIASS_DEVELOPBRANCH__
        if: steps.preflight.outputs.skip != 'true'
        run: git checkout __MAIASS_DEVELOPBRANCH__

      - name: Bump version
        if: steps.preflight.outputs.skip != 'true'
        run: maiass -a patch
        env:
          # Quoted: unquoted `off` is a YAML boolean that GitHub stringifies to
          # "false", and a repo's tracked .env.maiass (loaded with override) can
          # still flip AI back on — both previously minted a throwaway anonymous
          # subscription on every CI run. The CLI now also self-guards via CI
          # detection (see MAI-98), but keep this explicit and correct.
          MAIASS_AI_MODE: "off"  # Disable AI — no credits used in CI
MAIASS_CI_TEMPLATE_EOF
}

# Emit the raw GitLab CI excerpt template (placeholders intact).
maiass_ci_template_gitlab() {
  cat <<'MAIASS_CI_TEMPLATE_EOF'
# MAIASS — GitLab CI: Auto Version Bump on Merge to Develop
#
# What this does:
#   Runs `maiass -a patch` whenever a commit lands on your develop branch
#   (including merge requests). Bumps the patch version, commits, and pushes.
#
# Setup:
#   1. Set MAIASS_DEVELOPBRANCH in your .env.maiass if your develop branch
#      isn't called 'develop', then run `maiass --show-gl-excerpt` to print
#      this template with your branch name baked in (defaults to 'develop'
#      when unset).
#   2. Merge the printed excerpt into your existing .gitlab-ci.yml, or use it as-is
#   3. In GitLab: Settings → Repository → Protected branches → allow pipelines to push
#   4. Create a project access token or personal access token with write access
#   5. Add it as a CI/CD variable named GITLAB_TOKEN (masked, protected)
#
# Double-bump protection:
#   The script checks the last commit author and skips if it was already made
#   by the CI bot — preventing an infinite loop of version bumps.
#
# Missing-token behaviour:
#   If GITLAB_TOKEN is not set, a preflight (by default) fails the job with a
#   clear message. To instead skip with a warning and pass, set
#   MAIASS_CI_FAIL_SILENTLY to "true" in the variables: block below.

stages:
  - version

maiass-version-bump:
  stage: version
  image: node:20
  only:
    - __MAIASS_DEVELOPBRANCH__
  script:
    # Preflight: GITLAB_TOKEN is required to push the bump back. Behaviour when
    # it's missing is controlled by MAIASS_CI_FAIL_SILENTLY in the variables:
    # block below: false (default) fails the job; true skips with a warning.
    - |
      if [ -z "$GITLAB_TOKEN" ]; then
        MSG="GITLAB_TOKEN CI/CD variable is not set — add it (masked, protected) with write access to enable automatic version bumping."
        if [ "$MAIASS_CI_FAIL_SILENTLY" = "true" ]; then
          echo "WARNING: $MSG Skipping version bump."
          exit 0
        else
          echo "ERROR: $MSG"
          exit 1
        fi
      fi
    # Skip if the last commit was already a version bump from this pipeline
    - |
      LAST_AUTHOR=$(git log -1 --pretty=format:'%an')
      LAST_MSG=$(git log -1 --pretty=format:'%s')
      if echo "$LAST_AUTHOR" | grep -q "GitLab CI" || echo "$LAST_MSG" | grep -qiE '^Bumped version'; then
        echo "Version bump commit detected — skipping to avoid loop."
        exit 0
      fi
    - npm install -g maiass --no-fund --no-audit
    - git config user.name "GitLab CI"
    - git config user.email "ci@gitlab.com"
    # Authenticate push via HTTPS using the project token
    - git remote set-url origin "https://oauth2:${GITLAB_TOKEN}@${CI_SERVER_HOST}/${CI_PROJECT_PATH}.git"
    - maiass -a patch
  variables:
    MAIASS_AI_MODE: "off"  # Disable AI — no credits used in CI
    # Missing GITLAB_TOKEN: "false" fails the job, "true" skips with a warning.
    MAIASS_CI_FAIL_SILENTLY: "false"
MAIASS_CI_TEMPLATE_EOF
}

# Emit the raw Bitbucket Pipelines excerpt template (placeholders intact).
maiass_ci_template_bitbucket() {
  cat <<'MAIASS_CI_TEMPLATE_EOF'
# MAIASS — Bitbucket Pipelines: Auto Version Bump on Push to Develop
#
# What this does:
#   Runs `maiass -a patch` whenever a commit lands on your develop branch
#   (including merged pull requests). Bumps the patch version, commits, and pushes.
#
# ⚠️  Double-bump caveat:
#   Unlike GitHub Actions, Bitbucket Pipelines cannot trigger exclusively on
#   PR merge events — it fires on every push to the branch, including the
#   version bump commit itself. The script below guards against this by checking
#   the last commit message. If it looks like a MAIASS version bump, it exits early.
#
# Setup:
#   1. Set MAIASS_DEVELOPBRANCH in your .env.maiass if your develop branch
#      isn't called 'develop', then run `maiass --show-bb-excerpt` to print
#      this template with your branch name baked in (defaults to 'develop'
#      when unset).
#   2. Merge the printed excerpt into your bitbucket-pipelines.yml (or use as-is)
#   3. In Bitbucket: Repository Settings → Pipelines → SSH Keys
#      Add a key pair and grant write access, OR use an app password:
#        - Create an app password with Repositories: Read & Write scope
#        - Add it as a repository variable named BB_APP_PASSWORD (secured)
#        - Add your Bitbucket username as BB_USERNAME
#
# Missing-credential behaviour:
#   If BB_USERNAME / BB_APP_PASSWORD are not set, a preflight (by default) fails
#   the step with a clear message. To instead skip with a warning and pass, set
#   MAIASS_CI_FAIL_SILENTLY to "true" on the first line of the script below.

pipelines:
  branches:
    __MAIASS_DEVELOPBRANCH__:
      - step:
          name: MAIASS Version Bump
          image: node:20
          script:
            # Edit to "true" to skip with a warning instead of failing when the
            # push credential is missing. (Bitbucket doesn't reliably export a
            # step-level variables: block to the script, so it's set here.)
            - export MAIASS_CI_FAIL_SILENTLY="false"
            # Preflight: BB_USERNAME/BB_APP_PASSWORD are required to push the
            # bump back. Behaviour when missing is controlled by
            # MAIASS_CI_FAIL_SILENTLY above: false (default) fails the step;
            # true skips with a warning.
            - |
              if [ -z "$BB_USERNAME" ] || [ -z "$BB_APP_PASSWORD" ]; then
                MSG="BB_USERNAME / BB_APP_PASSWORD repository variables are not set — add them (app password with Repositories: Read & Write) to enable automatic version bumping."
                if [ "$MAIASS_CI_FAIL_SILENTLY" = "true" ]; then
                  echo "WARNING: $MSG Skipping version bump."
                  exit 0
                else
                  echo "ERROR: $MSG"
                  exit 1
                fi
              fi
            # Guard: skip if last commit was already a version bump
            - |
              LAST_MSG=$(git log -1 --pretty=format:'%s')
              if echo "$LAST_MSG" | grep -qiE '^Bumped version'; then
                echo "Version bump commit detected — skipping to avoid loop."
                exit 0
              fi
            - npm install -g maiass --no-fund --no-audit
            - git config user.name "Bitbucket Pipelines"
            - git config user.email "pipelines@bitbucket.org"
            # Authenticate push via app password
            - git remote set-url origin "https://${BB_USERNAME}:${BB_APP_PASSWORD}@bitbucket.org/${BITBUCKET_REPO_FULL_NAME}.git"
            - maiass -a patch
          variables:
            MAIASS_AI_MODE: "off"  # Disable AI — no credits used in CI
MAIASS_CI_TEMPLATE_EOF
}

# --create-gh-action: write the rendered GitHub Actions workflow into
# .github/workflows/maiass-version-bump.yml in the current project. Creates
# parent dirs; warns and skips if the target already exists (no overwrite).
# Mirrors node's createGithubAction()/copyTemplate().
create_github_action() {
  local target="$(pwd)/.github/workflows/maiass-version-bump.yml"

  if [[ -e "$target" ]]; then
    print_warning "$target already exists — skipping." "always"
    print_info "  Delete it first if you want a fresh copy." "always"
    return 0
  fi

  mkdir -p "$(dirname "$target")"
  maiass_ci_template_github | maiass_ci_render_template > "$target"

  print_success "Created $target" "always"
  print_info "  Next: add a GH_PAT secret in your repo → Settings → Secrets → Actions" "always"
}

# --show-gl-excerpt: print the rendered GitLab CI excerpt to stdout for manual
# merge into .gitlab-ci.yml. Mirrors node's showGitlabExcerpt()/showTemplate().
show_gitlab_excerpt() {
  print_success "" "always"
  print_success "MAIASS — GitLab CI excerpt (merge into your .gitlab-ci.yml)" "always"
  printf '%s\n' "------------------------------------------------------------"
  maiass_ci_template_gitlab | maiass_ci_render_template
  printf '%s\n' "------------------------------------------------------------"
  print_info "Copy the above into your .gitlab-ci.yml" "always"
}

# --show-bb-excerpt: print the rendered Bitbucket Pipelines excerpt to stdout
# for manual merge. Mirrors node's showBitbucketExcerpt()/showTemplate().
show_bitbucket_excerpt() {
  print_success "" "always"
  print_success "MAIASS — Bitbucket Pipelines excerpt (merge into your bitbucket-pipelines.yml)" "always"
  printf '%s\n' "------------------------------------------------------------"
  maiass_ci_template_bitbucket | maiass_ci_render_template
  printf '%s\n' "------------------------------------------------------------"
  print_info "Copy the above into your bitbucket-pipelines.yml" "always"
}

